   650	\begin{lemma}[Fourier cancellation over a subspace]\label{lem:cancellation}
   651		\lean{MIPStarRE.QPBT.ffChar_dotProduct_submodule_expect_eq_zero}
   652		\leanok
   653		\uses{def:dot-product-orthogonal, def:subfield-trace}
   654		Let $V$ be a subspace of $\F_q^k$ and let $\omega = e^{2\pi i/p}$, where
   655		$p$ is the characteristic of $\F_q$ and $\tr = \tr_{q \to p}$. For all
   656		$v \notin V^\perp$,
   657		\[
   658			\E_{\bu \sim V}\, \omega^{\tr(\bu \cdot v)} = 0\;,
   659		\]
   660		where the expectation is over a uniformly random vector $\bu$ in $V$.
   661	\end{lemma}
   662	\begin{proof}
   663		This is Fact 3.2 of \cite{Natarajan2018NEEXP}. Since $v \notin V^\perp$,
   664		the $\F_q$-linear functional $u \mapsto u \cdot v$ is not identically zero
   665		on $V$, hence surjective onto $\F_q$; composing with the nonzero map $\tr$
   666		shows that there is $u_0 \in V$ with $\tr(u_0 \cdot v) \neq 0$. Writing $C$
   667		for the expectation, translation invariance of the uniform distribution on
   668		$V$ gives
   669		$C = \E_{\bu \sim V}\, \omega^{\tr((\bu + u_0) \cdot v)}
   670		= \omega^{\tr(u_0 \cdot v)}\, C$, and $\omega^{\tr(u_0 \cdot v)} \neq 1$
   671		forces $C = 0$.
   672	\end{proof}
